#!/usr/bin/env python3
"""Make a dependency-free Canvas viewer from the generated surface viewer data."""
from __future__ import annotations
import argparse, base64, gzip, json, math, re
from pathlib import Path

PAGE = r'''<!doctype html><html lang="zh-CN"><meta charset="utf-8"><title>SMPL surface contact Canvas viewer</title><style>
html,body{margin:0;height:100%;font:14px system-ui,"Microsoft YaHei",sans-serif;background:#eef2f4;color:#17212b}.app{height:100%;display:grid;grid-template-rows:auto 1fr auto}.top,.bottom{background:#fff;padding:10px 14px;border-bottom:1px solid #ccd6dc}.top{display:flex;justify-content:space-between}.top h1{margin:0;font-size:18px}.top p{margin:3px 0;color:#65737d}.main{min-height:0;display:grid;grid-template-columns:1fr 270px}.view{min-width:0;min-height:0;background:#edf1f3}.view canvas{width:100%;height:100%;display:block}.side{background:#fff;border-left:1px solid #ccd6dc;padding:12px;overflow:auto}.side h2{font-size:14px;margin:0 0 8px}.side section+section{border-top:1px solid #e4e9ec;margin-top:12px;padding-top:12px}.metrics div{display:flex;justify-content:space-between;margin:5px 0}.metrics dt{color:#65737d}.metrics dd{margin:0;text-align:right}.checks{display:grid;gap:7px}.bottom{display:flex;gap:10px;align-items:center;border-top:1px solid #ccd6dc;border-bottom:0}.bottom input{flex:1}.badge{padding:4px 8px;border-radius:10px;background:#e3edf2;color:#175b75}button{padding:5px 9px;border:1px solid #aebbc2;border-radius:5px;background:white}button.play{color:white;background:#176b7e}
</style><div class="app"><header class="top"><div><h1>male SMPL 表面手脚接触拟合</h1><p>本地离线版 · 窗口 60..90 · 31 帧 · 无外部库</p></div><div><span id="stage" class="badge">—</span> <span id="frame">60 / 90</span></div></header><div class="main"><div class="view"><canvas id="cv"></canvas></div><aside class="side"><section><h2>当前帧</h2><dl class="metrics"><div><dt>COCO 3D 误差</dt><dd id="e3">—</dd></div><div><dt>手部 surface 中位</dt><dd id="hr">—</dd></div><div><dt>脚部 surface 中位</dt><dd id="fr">—</dd></div><div><dt>地面变换</dt><dd id="pose">—</dd></div></dl></section><section><h2>显示</h2><div class="checks"><label><input id="mesh" type="checkbox" checked> SMPL 表面</label><label><input id="walker" type="checkbox" checked> 助步器实体杆件</label><label><input id="walls" type="checkbox" checked> 两面网格墙</label><label><input id="handles" type="checkbox" checked> 扶手 capsule</label><label><input id="contact" type="checkbox" checked> 脚底/手掌接触点</label><label><input id="tri" type="checkbox" checked> 三角化点</label><label><input id="cameras" type="checkbox" checked> 相机侧面投影轨迹</label><label><input id="trails" type="checkbox" checked> 踝关节拖尾</label><label><input id="axes" type="checkbox" checked> 长坐标系</label></div></section><section><h2>操作</h2><p>左键拖动旋转（上下/左右方向按屏幕直觉），右键或 Shift+左键平移，滚轮缩放。橙色虚线表示被质量门拒绝但保留原始坐标的骨架边；红色脚底点表示低于地面。</p></section></aside></div><footer class="bottom"><button id="play" class="play">播放</button><input id="slider" type="range" min="0" max="30" value="0"><button id="reset">重置视角</button></footer></div><script id="data" type="application/json">DATA</script><script>
const d=JSON.parse(document.getElementById('data').textContent),canvas=document.getElementById('cv'),ctx=canvas.getContext('2d');const unpack=s=>new Float32Array(Uint8Array.from(atob(s),c=>c.charCodeAt(0)).buffer);Promise.all([unpack(d.v),unpack(d.w),unpack(d.t),unpack(d.he),unpack(d.c),unpack(d.a)]).then(([v,w,t,he,c,ankle])=>{const N=d.n,NV=d.nv,faces=d.faces,si=d.si,pi=d.pi,WN=d.wn.length,av=d.av;let fi=0,yaw=0.4,pitch=0.4,zoom=1.0,panX=0,panY=0,drag=false,dragMode='rotate',lastX=0,lastY=0,playing=false,lastT=0;function gv(i){return [v[fi*NV*3+3*i],-v[fi*NV*3+3*i+1],v[fi*NV*3+3*i+2]]}function project(p){const cy=Math.cos(yaw),sy=Math.sin(yaw),cp=Math.cos(pitch),sp=Math.sin(pitch);let x=p[0]*cy-p[1]*sy,y=p[0]*sy+p[1]*cy,z=p[2];let yy=(z-.85)*cp-y*sp,zz=(z-.85)*sp+y*cp;const s=Math.min(canvas.width,canvas.height)*.9*zoom/(2.0+zz*.15);return [canvas.width*.5+panX+x*s,canvas.height*.56+panY-yy*s,zz]}function seg(a,b,color,width=2){const A=project(a),B=project(b);ctx.strokeStyle=color;ctx.lineWidth=width;ctx.lineCap='round';ctx.beginPath();ctx.moveTo(A[0],A[1]);ctx.lineTo(B[0],B[1]);ctx.stroke();ctx.lineCap='butt'}function dot(p,color,r){const q=project(p);ctx.fillStyle=color;ctx.beginPath();ctx.arc(q[0],q[1],r,0,7);ctx.fill()}function draw(){const W=canvas.clientWidth*devicePixelRatio,H=canvas.clientHeight*devicePixelRatio;if(canvas.width!==W||canvas.height!==H){canvas.width=W;canvas.height=H}ctx.clearRect(0,0,W,H);ctx.fillStyle='#edf1f3';ctx.fillRect(0,0,W,H);const ground=[project([-4,-4,0]),project([4,-4,0]),project([4,4,0]),project([-4,4,0])];ctx.fillStyle='#718279';ctx.beginPath();ctx.moveTo(ground[0][0],ground[0][1]);for(const q of ground.slice(1))ctx.lineTo(q[0],q[1]);ctx.closePath();ctx.fill();if(document.getElementById('walls').checked){const wallX=[[-4,-4,0],[-4,4,0],[-4,4,2.4],[-4,-4,2.4]],wallY=[[-4,4,0],[4,4,0],[4,4,2.4],[-4,4,2.4]];for(const poly of [wallX,wallY]){const q=poly.map(project);ctx.fillStyle='#d8e0e3';ctx.globalAlpha=.38;ctx.beginPath();ctx.moveTo(q[0][0],q[0][1]);for(const pt of q.slice(1))ctx.lineTo(pt[0],pt[1]);ctx.closePath();ctx.fill();ctx.globalAlpha=.9;for(let k=0;k<4;k++){const A=q[k],B=q[(k+1)%4];ctx.strokeStyle='#9eacb2';ctx.lineWidth=1.5;ctx.beginPath();ctx.moveTo(A[0],A[1]);ctx.lineTo(B[0],B[1]);ctx.stroke()}}ctx.globalAlpha=.62;for(let yy=-3;yy<=3;yy++){seg([-4,yy,0],[-4,yy,2.4],'#b9c8c0',1);seg([yy,4,0],[yy,4,2.4],'#b9c8c0',1)}for(let zz=.4;zz<=2.0;zz+=.4){seg([-4,-4,zz],[-4,4,zz],'#b9c8c0',1);seg([-4,4,zz],[4,4,zz],'#b9c8c0',1)}ctx.globalAlpha=1}ctx.save();ctx.globalAlpha=.85;for(let k=-4;k<=4;k++){seg([k,-4,0],[k,4,0],'#b9c8c0',1);seg([-4,k,0],[4,k,0],'#b9c8c0',1)}ctx.restore();if(document.getElementById('axes').checked){seg([0,0,0],[4.5,0,0],'#ba3030',4);seg([0,0,0],[0,4.5,0],'#1c7a43',4);seg([0,0,0],[0,0,2.5],'#365bb5',4);dot([4.5,0,0],'#ba3030',5);dot([0,4.5,0],'#1c7a43',5);dot([0,0,2.5],'#365bb5',5)}if(document.getElementById('trails').checked){for(let q=Math.max(0,fi-12);q<fi;q++){for(let side=0;side<2;side++)if(av[q*2+side]){const p=[ankle[q*6+side*3],-ankle[q*6+side*3+1],0];dot(p,side?'#8b5a20':'#1e6b8b',Math.max(1.5,3-(fi-q)*.12))}}}if(document.getElementById('cameras').checked){const sideX=-3.8;seg([sideX,-4,0],[sideX,4,0],'#9daab0',1);for(let side=0;side<2;side++){let prev=null;for(let q=Math.max(0,fi-30);q<=fi;q++){const projected=[sideX,-c[q*6+side*3+1],c[q*6+side*3+2]];if(prev)seg(prev,projected,side?'#7b3f98':'#aa4a18',3);prev=projected}const p=[c[fi*6+side*3],-c[fi*6+side*3+1],c[fi*6+side*3+2]],projected=[sideX,p[1],p[2]];ctx.setLineDash([4,4]);seg(p,projected,'#819199',1);ctx.setLineDash([]);dot(p,side?'#7b3f98':'#aa4a18',5);dot(projected,side?'#7b3f98':'#aa4a18',5)}}if(document.getElementById('mesh').checked){const tris=[];for(const f of faces){const a=gv(f[0]),b=gv(f[1]),c=gv(f[2]),A=project(a),B=project(b),C=project(c);tris.push([A[2]+B[2]+C[2],A,B,C])}tris.sort((a,b)=>b[0]-a[0]);ctx.globalAlpha=.45;for(const q of tris){ctx.fillStyle=`hsl(${28+Math.max(0,Math.min(1,q[3][1]/H))*22},45%,58%)`;ctx.beginPath();ctx.moveTo(q[1][0],q[1][1]);ctx.lineTo(q[2][0],q[2][1]);ctx.lineTo(q[3][0],q[3][1]);ctx.closePath();ctx.fill()}ctx.globalAlpha=1}if(document.getElementById('contact').checked){for(const idx of si){const p=gv(idx);dot(p,p[2]<0?'#c62828':'#1b7f4a',p[2]<0?4.5:3.0)}}if(document.getElementById('walker').checked){const used=new Set();for(const e of d.we){const a=wn(e[0]),b=wn(e[1]);used.add(e[0]);used.add(e[1]);seg(a,b,'#0d3640',11);seg(a,b,'#176b7e',7)}for(const i of used){dot(wn(i),'#0d3640',6);dot(wn(i),'#2a8a9a',4)}}if(document.getElementById('handles').checked){for(let s=0;s<2;s++){const a=[he[fi*12+s*6],-he[fi*12+s*6+1],he[fi*12+s*6+2]],b=[he[fi*12+s*6+3],-he[fi*12+s*6+4],he[fi*12+s*6+5]];seg(a,b,'#55305f',9);seg(a,b,s?'#6a1b9a':'#f57c00',5)}}if(document.getElementById('contact').checked){for(const idx of pi)dot(gv(idx),'#8e24aa',2)}if(document.getElementById('tri').checked){for(let j=0;j<17;j++)if(d.acc[fi*17+j]){const p=[t[fi*51+3*j],-t[fi*51+3*j+1],t[fi*51+3*j+2]];dot(p,'#c62828',3)}}document.getElementById('stage').textContent=d.stage[fi];document.getElementById('frame').textContent=`${d.ids[fi]} / ${d.ids[N-1]}`;document.getElementById('e3').textContent=(d.e3[fi]===null?'—':d.e3[fi].toFixed(1)+' mm');document.getElementById('hr').textContent=(d.hm[fi]===null?'—':(d.hm[fi]*1000).toFixed(1)+' mm');document.getElementById('fr').textContent=(d.fm[fi]===null?'—':(d.fm[fi]*1000).toFixed(1)+' mm');document.getElementById('pose').textContent=d.pose[fi];}function wn(i){return [w[fi*WN*3+3*i],-w[fi*WN*3+3*i+1],w[fi*WN*3+3*i+2]]}document.getElementById('slider').oninput=e=>{fi=+e.target.value;playing=false;document.getElementById('play').textContent='播放';draw()};document.getElementById('play').onclick=()=>{playing=!playing;document.getElementById('play').textContent=playing?'暂停':'播放'};document.getElementById('reset').onclick=()=>{yaw=.4;pitch=.4;zoom=1;panX=0;panY=0;draw()};document.querySelectorAll('.checks input').forEach(x=>x.onchange=draw);canvas.oncontextmenu=e=>e.preventDefault();canvas.onpointerdown=e=>{drag=true;dragMode=(e.button===2||e.shiftKey)?'pan':'rotate';lastX=e.clientX;lastY=e.clientY;canvas.setPointerCapture?.(e.pointerId);e.preventDefault()};canvas.onpointerup=e=>{drag=false;canvas.releasePointerCapture?.(e.pointerId)};canvas.onpointercancel=()=>drag=false;canvas.onpointermove=e=>{if(!drag)return;const dx=e.clientX-lastX,dy=e.clientY-lastY;lastX=e.clientX;lastY=e.clientY;if(dragMode==='pan'){panX+=dx*devicePixelRatio;panY+=dy*devicePixelRatio}else{yaw+=dx*.007;pitch=Math.max(-1.48,Math.min(1.48,pitch+dy*.007))}draw()};canvas.onwheel=e=>{e.preventDefault();zoom=Math.max(.15,Math.min(8,zoom*(e.deltaY<0?1.08:.93)));draw()};function loop(t){if(playing&&t-lastT>33){fi=(fi+1)%N;document.getElementById('slider').value=fi;lastT=t;draw()}requestAnimationFrame(loop)}onresize=draw;draw();loop(0)}).catch(e=>{document.body.insertAdjacentHTML('beforeend','<pre style="color:#b00;padding:20px">Viewer initialization failed: '+e+'</pre>')});
</script></html>'''

def main() -> int:
    p=argparse.ArgumentParser();p.add_argument('--source',type=Path,required=True);p.add_argument('--output',type=Path,required=True);a=p.parse_args();s=a.source.read_text(encoding='utf-8');m=re.search(r'<script id="data" type="application/json">(.*?)</script>',s,re.S)
    if not m: raise RuntimeError('source viewer has no embedded data')
    data=json.loads(m.group(1))
    for key in ('v','w','t','he','j','c','a'):
        data[key]=base64.b64encode(gzip.decompress(base64.b64decode(data[key]))).decode('ascii')
    def finite_json(value):
        if isinstance(value,float) and not math.isfinite(value): return None
        if isinstance(value,list): return [finite_json(x) for x in value]
        if isinstance(value,dict): return {k:finite_json(v) for k,v in value.items()}
        return value
    data=finite_json(data)
    page = PAGE.replace('DATA', json.dumps(data, ensure_ascii=False, allow_nan=False, separators=(',', ':')))
    page = page.replace('窗口 60..90 · 31 帧 · 无外部库', f'全片 0..{int(data["n"])-1} · {int(data["n"])} 帧 · 无外部库')
    page = page.replace('min="0" max="30" value="0"', f'min="0" max="{int(data["n"])-1}" value="0"')
    page = page.replace('<label><input id="walker" type="checkbox" checked> 助步器实体杆件</label>', '<label><input id="walker" type="checkbox" checked> 助步器实体杆件</label><label><input id="links" type="checkbox" checked> 人体骨架线</label>')
    page = page.replace("const N=d.n,NV=d.nv,faces=d.faces,si=d.si,pi=d.pi,WN=d.wn.length,av=d.av;", "const N=d.n,NV=d.nv,faces=d.faces,si=d.si,pi=d.pi,WN=d.wn.length,av=d.av,E=[[5,6],[5,7],[7,9],[6,8],[8,10],[5,11],[6,12],[11,12],[11,13],[13,15],[12,14],[14,16],[0,1],[0,2],[1,3],[2,4]];")
    # The page background stays light; only the projected Z=0 ground polygon is dark.
    marker = "if(document.getElementById('walker').checked){"
    skeleton = "if(document.getElementById('links').checked){for(const e of E){const a=e[0],b=e[1],A=[t[fi*51+3*a],-t[fi*51+3*a+1],t[fi*51+3*a+2]],B=[t[fi*51+3*b],-t[fi*51+3*b+1],t[fi*51+3*b+2]];if(!A.every(Number.isFinite)||!B.every(Number.isFinite))continue;const accepted=d.acc[fi*17+a]&&d.acc[fi*17+b];if(!accepted)ctx.setLineDash([6,4]);seg(A,B,accepted?'#101820':'#b36b1e',accepted?3:2);ctx.setLineDash([])}}"
    page = page.replace(marker, skeleton + marker)
    a.output.write_text(page, encoding='utf-8'); print(a.output.resolve()); return 0
if __name__=='__main__':raise SystemExit(main())
